"use client";

import { useMemo, useState } from "react";
import { Search, SlidersHorizontal } from "lucide-react";

export default function TransactionTable({ transactions }: { transactions: any[] }) {
  const [query, setQuery] = useState("");
  const [status, setStatus] = useState("ALL");
  const filtered = useMemo(() => transactions.filter((transaction) => {
    const haystack = `${transaction.reference || ""} ${transaction.description || ""} ${transaction.type || ""}`.toLowerCase();
    return haystack.includes(query.toLowerCase()) && (status === "ALL" || transaction.status === status);
  }), [transactions, query, status]);

  return <div className="overflow-hidden rounded-2xl border border-slate-800 bg-slate-900 shadow-xl"><div className="flex flex-col gap-4 border-b border-slate-800 p-5 sm:flex-row sm:items-center sm:justify-between"><div><h3 className="text-base font-semibold text-white">Transaction history</h3><p className="mt-1 text-xs text-slate-400">Search and filter activity across your accounts.</p></div><div className="flex flex-col gap-2 sm:flex-row"><label className="relative"><Search size={14} className="absolute left-3 top-3 text-slate-500" aria-hidden="true" /><input aria-label="Search transactions" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search transactions" className="w-full rounded-lg border border-slate-800 bg-slate-950 py-2.5 pl-9 pr-3 text-xs text-slate-200 outline-none focus:border-indigo-500 sm:w-52" /></label><label className="relative"><SlidersHorizontal size={14} className="absolute left-3 top-3 text-slate-500" aria-hidden="true" /><select aria-label="Filter transaction status" value={status} onChange={(event) => setStatus(event.target.value)} className="w-full appearance-none rounded-lg border border-slate-800 bg-slate-950 py-2.5 pl-9 pr-8 text-xs text-slate-300 outline-none focus:border-indigo-500 sm:w-40"><option value="ALL">All statuses</option><option value="COMPLETED">Completed</option><option value="PENDING">Pending</option><option value="FAILED">Failed</option></select></label></div></div><div className="overflow-x-auto"><table className="w-full text-left"><thead><tr className="border-b border-slate-800 bg-slate-950/60 text-[10px] uppercase tracking-wider text-slate-500"><th className="px-5 py-3">Reference</th><th className="px-5 py-3">Type</th><th className="px-5 py-3">Amount</th><th className="px-5 py-3">Date</th><th className="px-5 py-3 text-right">Status</th></tr></thead><tbody className="divide-y divide-slate-800">{filtered.length ? filtered.map((transaction) => <tr key={transaction.id} className="text-xs text-slate-300 hover:bg-slate-800/40"><td className="max-w-60 px-5 py-4"><span className="block truncate font-mono font-semibold text-indigo-300">{transaction.reference || transaction.id}</span><span className="mt-1 block truncate text-slate-500">{transaction.description || "No description"}</span></td><td className="px-5 py-4 text-slate-300">{transaction.type || "TRANSFER"}</td><td className="whitespace-nowrap px-5 py-4 font-mono text-white">${Number(transaction.amount || 0).toLocaleString(undefined, { minimumFractionDigits: 2 })}</td><td className="whitespace-nowrap px-5 py-4 text-slate-500">{new Date(transaction.createdAt).toLocaleDateString()}</td><td className="px-5 py-4 text-right"><span className={`rounded-full border px-2 py-1 text-[10px] ${transaction.status === "FAILED" ? "border-red-500/20 bg-red-500/10 text-red-300" : transaction.status === "PENDING" ? "border-amber-500/20 bg-amber-500/10 text-amber-300" : "border-emerald-500/20 bg-emerald-500/10 text-emerald-300"}`}>{transaction.status || "COMPLETED"}</span></td></tr>) : <tr><td colSpan={5} className="px-5 py-14 text-center text-xs text-slate-500">No transactions match your filters.</td></tr>}</tbody></table></div></div>;
}